import * as React from "react";

import {Card, type PiCardProps} from "@pihanga2/core";
import {Empty, EmptyContent, EmptyMedia} from "@/components/ui/empty";
import {getIcon} from "@/cards/icons";
import type {EmptyCardProps} from "./emptyCard.types";

export const EmptyCardComponent = (
  props: PiCardProps<EmptyCardProps>,
): React.ReactNode => {
  const {icon, content, className, style, cardName} = props;

  return (
    <Empty className={className} style={style} data-pihanga={cardName}>
      {icon && <EmptyMedia variant="icon">{getIcon(icon)}</EmptyMedia>}
      {content && (
        <EmptyContent>
          <Card cardName={content} parentCard={cardName} />
        </EmptyContent>
      )}
    </Empty>
  );
};

import {createCardDeclaration, type PiCardRef} from "@pihanga2/core";
import type React from "react";

export const EMPTY_CARD = "empty-card";

export type EmptyCardProps = {
  /**
   * Icon name from the pihanga icon registry.
   * When provided, renders an `EmptyMedia` slot with `variant="icon"`.
   */
  icon?: string;

  /**
   * Pihanga card reference rendered inside `EmptyContent`.
   * Use this to show a call-to-action button, form, or any other card.
   */
  content?: PiCardRef;

  /** Additional Tailwind / CSS classes forwarded to the root `Empty` element. */
  className?: string;

  /** Inline styles forwarded to the root `Empty` element. */
  style?: React.CSSProperties;
};

/**
 * Factory function for declaring an `empty-card` instance.
 *
 * ```ts
 * import {registerCard} from "@pihanga2/core";
 * import {EmptyCard} from "@/cards/emptyCard";
 * import {Button} from "@/cards/button";
 *
 * registerCard("myApp/noResults", EmptyCard({
 *   icon: "search",
 *   content: "myApp/createButton",
 * }));
 *
 * registerCard("myApp/createButton", Button({label: "Create new"}));
 * ```
 */
export const EmptyCard = createCardDeclaration<EmptyCardProps>(EMPTY_CARD);

import {registerCardComponent} from "@pihanga2/core";

import {EmptyCardComponent} from "./emptyCard.component";
import {EMPTY_CARD} from "./emptyCard.types";

export * from "./emptyCard.types";

registerCardComponent({
  name: EMPTY_CARD,
  component: EmptyCardComponent,
});
